import 'dart:async'; import 'dart:math'; import 'package:flutter/material.dart'; import 'package:flutter/services.dart'; import 'package:shared_preferences/shared_preferences.dart'; void main() { runApp(const SpaceShooterApp()); } class SpaceShooterApp extends StatelessWidget { const SpaceShooterApp({super.key}); @override Widget build(BuildContext context) { return MaterialApp( debugShowCheckedModeBanner: false, title: 'Space Shooter', theme: ThemeData( scaffoldBackgroundColor: Colors.black, fontFamily: 'monospace', ), home: const StartScreen(), ); } } // ============================================ // GAME DATA MODELS // ============================================ class Bullet { double x, y; double speed; bool isEnemy; Bullet(this.x, this.y, {this.speed = 10, this.isEnemy = false}); } class Enemy { double x, y; double speed; int health; int maxHealth; double size; Color color; String type; // 'straight', 'zigzag' double zigzagOffset = 0; Enemy({ required this.x, required this.y, required this.speed, required this.health, required this.size, required this.color, required this.type, }) : maxHealth = health; } class Boss extends Enemy { double shootCooldown = 0; Boss({ required super.x, required super.y, required super.speed, required super.health, required super.size, required super.color, }) : super(type: 'boss'); } class Star { double x, y, speed, size; Star(this.x, this.y, this.speed, this.size); } // ============================================ // SKILL TREE DATA // ============================================ class Skill { String id; String name; String branch; // offense, defense, mobility int cost; bool unlocked; String? requires; Skill({ required this.id, required this.name, required this.branch, required this.cost, this.unlocked = false, this.requires, }); } class SkillManager { static List<Skill> skills = [ // Offense Skill(id: 'damage1', name: 'Damage+', branch: 'offense', cost: 50), Skill(id: 'firerate1', name: 'Fire Rate+', branch: 'offense', cost: 75, requires: 'damage1'), Skill(id: 'doubleshot', name: 'Double Shot', branch: 'offense', cost: 150, requires: 'firerate1'), Skill(id: 'tripleshot', name: 'Triple Shot', branch: 'offense', cost: 300, requires: 'doubleshot'), // Defense Skill(id: 'health1', name: 'Max Health+', branch: 'defense', cost: 50), Skill(id: 'shield', name: 'Shield', branch: 'defense', cost: 100, requires: 'health1'), Skill(id: 'regen', name: 'Health Regen', branch: 'defense', cost: 200, requires: 'shield'), // Mobility Skill(id: 'speed1', name: 'Speed+', branch: 'mobility', cost: 50), Skill(id: 'dash', name: 'Dash', branch: 'mobility', cost: 100, requires: 'speed1'), Skill(id: 'dodge', name: 'Dodge Chance', branch: 'mobility', cost: 250, requires: 'dash'), ]; static Future<void> loadSkills() async { final prefs = await SharedPreferences.getInstance(); for (var skill in skills) { skill.unlocked = prefs.getBool(skill.id) ?? false; } } static Future<void> saveSkill(String id) async { final prefs = await SharedPreferences.getInstance(); await prefs.setBool(id, true); } static bool isUnlocked(String id) { return skills.firstWhere((s) => s.id == id).unlocked; } static bool canUnlock(Skill skill) { if (skill.unlocked) return false; if (skill.requires == null) return true; return isUnlocked(skill.requires!); } static int getBonusDamage() => isUnlocked('damage1') ? 1 : 0; static double getFireRateMultiplier() => isUnlocked('firerate1') ? 0.7 : 1.0; static int getBulletCount() { if (isUnlocked('tripleshot')) return 3; if (isUnlocked('doubleshot')) return 2; return 1; } static int getBonusHealth() => isUnlocked('health1') ? 1 : 0; static bool hasShield() => isUnlocked('shield'); static bool hasRegen() => isUnlocked('regen'); static double getSpeedMultiplier() => isUnlocked('speed1') ? 1.3 : 1.0; static bool hasDash() => isUnlocked('dash'); static double getDodgeChance() => isUnlocked('dodge') ? 0.15 : 0.0; } // ============================================ // START SCREEN // ============================================ class StartScreen extends StatefulWidget { const StartScreen({super.key}); @override State<StartScreen> createState() => _StartScreenState(); } class _StartScreenState extends State<StartScreen> { int coins = 0; @override void initState() { super.initState(); _loadCoins(); SkillManager.loadSkills(); } Future<void> _loadCoins() async { final prefs = await SharedPreferences.getInstance(); setState(() { coins = prefs.getInt('coins') ?? 0; }); } @override Widget build(BuildContext context) { return Scaffold( body: Container( decoration: const BoxDecoration( gradient: LinearGradient( begin: Alignment.topCenter, end: Alignment.bottomCenter, colors: [Colors.black, Color(0xFF0a0a2a)], ), ), child: Center( child: Column( mainAxisAlignment: MainAxisAlignment.center, children: [ const Icon(Icons.rocket_launch, color: Colors.cyanAccent, size: 80), const SizedBox(height: 20), const Text( 'SPACE SHOOTER', style: TextStyle( color: Colors.cyanAccent, fontSize: 32, fontWeight: FontWeight.bold, letterSpacing: 4, ), ), const SizedBox(height: 10), Text( '💰 Coins: $coins', style: const TextStyle(color: Colors.yellow, fontSize: 18), ), const SizedBox(height: 50), _buildButton('▶ START GAME', Colors.green, () { Navigator.push( context, MaterialPageRoute(builder: (_) => const GameScreen()), ).then((_) => _loadCoins()); }), const SizedBox(height: 20), _buildButton('🌳 SKILL TREE', Colors.purpleAccent, () { Navigator.push( context, MaterialPageRoute(builder: (_) => const SkillTreeScreen()), ).then((_) => _loadCoins()); }), ], ), ), ), ); } Widget _buildButton(String text, Color color, VoidCallback onTap) { return GestureDetector( onTap: onTap, child: Container( width: 250, padding: const EdgeInsets.symmetric(vertical: 15), decoration: BoxDecoration( color: color.withOpacity(0.2), border: Border.all(color: color, width: 2), borderRadius: BorderRadius.circular(8), ), child: Text( text, textAlign: TextAlign.center, style: TextStyle(color: color, fontSize: 18, fontWeight: FontWeight.bold), ), ), ); } } // ============================================ // SKILL TREE SCREEN // ============================================ class SkillTreeScreen extends StatefulWidget { const SkillTreeScreen({super.key}); @override State<SkillTreeScreen> createState() => _SkillTreeScreenState(); } class _SkillTreeScreenState extends State<SkillTreeScreen> { int coins = 0; @override void initState() { super.initState(); _load(); } Future<void> _load() async { final prefs = await SharedPreferences.getInstance(); await SkillManager.loadSkills(); setState(() { coins = prefs.getInt('coins') ?? 0; }); } Future<void> _buySkill(Skill skill) async { if (coins >= skill.cost && SkillManager.canUnlock(skill)) { final prefs = await SharedPreferences.getInstance(); setState(() { coins -= skill.cost; skill.unlocked = true; }); await prefs.setInt('coins', coins); await SkillManager.saveSkill(skill.id); } } Widget _buildBranch(String branch, Color color, String title) { final branchSkills = SkillManager.skills.where((s) => s.branch == branch).toList(); return Expanded( child: Column( children: [ Text(title, style: TextStyle(color: color, fontSize: 16, fontWeight: FontWeight.bold)), const SizedBox(height: 10), ...branchSkills.map((skill) { bool canBuy = SkillManager.canUnlock(skill) && coins >= skill.cost; bool locked = !skill.unlocked && !SkillManager.canUnlock(skill); return GestureDetector( onTap: skill.unlocked ? null : () => _buySkill(skill), child: Container( margin: const EdgeInsets.symmetric(vertical: 5, horizontal: 8), padding: const EdgeInsets.all(10), decoration: BoxDecoration( color: skill.unlocked ? color.withOpacity(0.3) : locked ? Colors.grey.withOpacity(0.1) : Colors.white.withOpacity(0.05), border: Border.all( color: skill.unlocked ? color : (locked ? Colors.grey : color.withOpacity(0.5)), width: 2, ), borderRadius: BorderRadius.circular(6), ), child: Column( children: [ Text( skill.name, textAlign: TextAlign.center, style: TextStyle( color: skill.unlocked ? color : (locked ? Colors.grey : Colors.white), fontSize: 13, fontWeight: FontWeight.bold, ), ), const SizedBox(height: 4), if (skill.unlocked) const Icon(Icons.check_circle, color: Colors.green, size: 16) else Text( '💰${skill.cost}', style: TextStyle( color: canBuy ? Colors.yellow : Colors.grey, fontSize: 12, ), ), ], ), ), ); }), ], ), ); } @override Widget build(BuildContext context) { return Scaffold( backgroundColor: Colors.black, appBar: AppBar( backgroundColor: Colors.black, title: Text('SKILL TREE 💰$coins', style: const TextStyle(color: Colors.cyanAccent)), iconTheme: const IconThemeData(color: Colors.cyanAccent), ), body: Padding( padding: const EdgeInsets.all(8.0), child: Row( children: [ _buildBranch('offense', Colors.redAccent, '🔫 OFFENSE'), _buildBranch('defense', Colors.blueAccent, '🛡️ DEFENSE'), _buildBranch('mobility', Colors.yellowAccent, '⚡ MOBILITY'), ], ), ), ); } } // ============================================ // GAME SCREEN (MAIN GAMEPLAY) // ============================================ class GameScreen extends StatefulWidget { const GameScreen({super.key}); @override State<GameScreen> createState() => _GameScreenState(); } class _GameScreenState extends State<GameScreen> with SingleTickerProviderStateMixin { late Ticker _ticker; Duration _lastTime = Duration.zero; // Player double playerX = 0; double playerY = 0; int maxHealth = 3; int health = 3; double shootCooldown = 0; double dashCooldown = 0; double shieldCooldown = 0; double regenTimer = 0; // Game state List<Bullet> bullets = []; List<Bullet> enemyBullets = []; List<Enemy> enemies = []; List<Star> stars = []; Boss? boss; int score = 0; int coins = 0; double enemySpawnTimer = 0; double difficulty = 1.0; bool isGameOver = false; bool isPaused = false; bool bossSpawnedThisLevel = false; final Random rand = Random(); Size screenSize = const Size(400, 800); @override void initState() { super.initState(); maxHealth = 3 + SkillManager.getBonusHealth(); health = maxHealth; _initStars(); _ticker = createTicker(_gameLoop)..start(); } void _initStars() { for (int i = 0; i < 50; i++) { stars.add(Star( rand.nextDouble() * 400, rand.nextDouble() * 800, rand.nextDouble() * 2 + 1, rand.nextDouble() * 2 + 1, )); } } @override void didChangeDependencies() { super.didChangeDependencies(); final size = MediaQuery.of(context).size; screenSize = size; if (playerX == 0 && playerY == 0) { playerX = size.width / 2; playerY = size.height - 100; } } void _gameLoop(Duration elapsed) { if (isGameOver || isPaused) return; double dt = (elapsed - _lastTime).inMilliseconds / 1000.0; _lastTime = elapsed; if (dt > 0.1) dt = 0.1; // clamp setState(() { _update(dt); }); } void _update(double dt) { // Update stars for (var star in stars) { star.y += star.speed * 60 * dt; if (star.y > screenSize.height) { star.y = 0; star.x = rand.nextDouble() * screenSize.width; } } // Auto shoot shootCooldown -= dt; if (shootCooldown <= 0) { _shoot(); shootCooldown = 0.3 * SkillManager.getFireRateMultiplier(); } if (dashCooldown > 0) dashCooldown -= dt; if (shieldCooldown > 0) shieldCooldown -= dt; // Regen if (SkillManager.hasRegen()) { regenTimer += dt; if (regenTimer >= 30 && health < maxHealth) { health++; regenTimer = 0; } } // Move bullets bullets.removeWhere((b) { b.y -= b.speed * 60 * dt; return b.y < -20; }); enemyBullets.removeWhere((b) { b.y += b.speed * 60 * dt; return b.y > screenSize.height + 20; }); // Spawn enemies enemySpawnTimer -= dt; if (enemySpawnTimer <= 0 && boss == null) { _spawnEnemy(); enemySpawnTimer = max(0.5, 1.5 - difficulty * 0.1); } // Move enemies for (var enemy in enemies) { enemy.y += enemy.speed * 60 * dt; if (enemy.type == 'zigzag') { enemy.zigzagOffset += dt * 3; enemy.x += sin(enemy.zigzagOffset) * 2; } } enemies.removeWhere((e) => e.y > screenSize.height + 50); // Boss logic if (boss != null) { boss!.x += sin(_lastTime.inMilliseconds / 500) * 2; boss!.shootCooldown -= dt; if (boss!.shootCooldown <= 0) { enemyBullets.add(Bullet(boss!.x - 10, boss!.y + 30, speed: 5, isEnemy: true)); enemyBullets.add(Bullet(boss!.x + 10, boss!.y + 30, speed: 5, isEnemy: true)); enemyBullets.add(Bullet(boss!.x, boss!.y + 30, speed: 5, isEnemy: true)); boss!.shootCooldown = 1.5; } } _checkCollisions(); // Difficulty scaling difficulty = 1.0 + (score / 1000) * 0.1; // Boss spawn every 5000 points if (score > 0 && score % 5000 < 50 && boss == null && !bossSpawnedThisLevel) { _spawnBoss(); bossSpawnedThisLevel = true; } if (score % 5000 > 100) { bossSpawnedThisLevel = false; } if (health <= 0) { _gameOver(); } } void _shoot() { int count = SkillManager.getBulletCount(); if (count == 1) { bullets.add(Bullet(playerX, playerY - 20)); } else if (count == 2) { bullets.add(Bullet(playerX - 10, playerY - 20)); bullets.add(Bullet(playerX + 10, playerY - 20)); } else { bullets.add(Bullet(playerX - 15, playerY - 20)); bullets.add(Bullet(playerX, playerY - 25)); bullets.add(Bullet(playerX + 15, playerY - 20)); } } void _spawnEnemy() { double x = rand.nextDouble() * (screenSize.width - 40) + 20; String type = rand.nextBool() ? 'straight' : 'zigzag'; enemies.add(Enemy( x: x, y: -30, speed: (1.5 + difficulty * 0.3), health: 1, size: 25, color: type == 'zigzag' ? Colors.orangeAccent : Colors.redAccent, type: type, )); } void _spawnBoss() { boss = Boss( x: screenSize.width / 2, y: 100, speed: 0, health: 50, size: 80, color: Colors.purpleAccent, ); } void _checkCollisions() { int baseDamage = 1 + SkillManager.getBonusDamage(); // Player bullets vs enemies bullets.removeWhere((bullet) { bool hit = false; enemies.removeWhere((enemy) { if (_isColliding(bullet.x, bullet.y, 5, enemy.x, enemy.y, enemy.size)) { enemy.health -= baseDamage; hit = true; if (enemy.health <= 0) { score += 100; coins += 5; return true; } } return false; }); // vs boss if (boss != null && _isColliding(bullet.x, bullet.y, 5, boss!.x, boss!.y, boss!.size)) { boss!.health -= baseDamage; hit = true; if (boss!.health <= 0) { score += 2000; coins += 100; boss = null; } } return hit; }); // Enemy bullets vs player enemyBullets.removeWhere((bullet) { if (_isColliding(bullet.x, bullet.y, 5, playerX, playerY, 20)) { _takeDamage(); return true; } return false; }); // Enemies vs player (direct collision) enemies.removeWhere((enemy) { if (_isColliding(enemy.x, enemy.y, enemy.size, playerX, playerY, 20)) { _takeDamage(); return true; } return false; }); } bool _isColliding(double x1, double y1, double s1, double x2, double y2, double s2) { double dx = x1 - x2; double dy = y1 - y2; double distance = sqrt(dx * dx + dy * dy); return distance < (s1 + s2) / 2; } void _takeDamage() { if (SkillManager.hasShield() && shieldCooldown <= 0) { shieldCooldown = 10; return; } if (SkillManager.getDodgeChance() > 0 && rand.nextDouble() < SkillManager.getDodgeChance()) { return; } health--; } void _gameOver() async { isGameOver = true; _ticker.stop(); final prefs = await SharedPreferences.getInstance(); int currentCoins = prefs.getInt('coins') ?? 0; await prefs.setInt('coins', currentCoins + coins); } void _movePlayer(double dx, double dy) { double speed = SkillManager.getSpeedMultiplier(); setState(() { playerX = (playerX + dx * speed).clamp(20, screenSize.width - 20); playerY = (playerY + dy * speed).clamp(20, screenSize.height - 20); }); } void _dash(double dx, double dy) { if (SkillManager.hasDash() && dashCooldown <= 0) { setState(() { playerX = (playerX + dx * 100).clamp(20, screenSize.width - 20); playerY = (playerY + dy * 100).clamp(20, screenSize.height - 20); dashCooldown = 3; }); } } void _restart() { setState(() { health = maxHealth; score = 0; coins = 0; bullets.clear(); enemyBullets.clear(); enemies.clear(); boss = null; isGameOver = false; difficulty = 1.0; playerX = screenSize.width / 2; playerY = screenSize.height - 100; }); _lastTime = Duration.zero; _ticker.start(); } @override void dispose() { _ticker.dispose(); super.dispose(); } @override Widget build(BuildContext context) { screenSize = MediaQuery.of(context).size; return Scaffold( backgroundColor: Colors.black, body: Stack( children: [ GestureDetector( onPanUpdate: (details) { if (!isGameOver) { _movePlayer(details.delta.dx, details.delta.dy); } }, onDoubleTap: () { _dash(0, -1); // dash upward on double tap }, child: CustomPaint( size: Size.infinite, painter: GamePainter( stars: stars, playerX: playerX, playerY: playerY, bullets: bullets, enemyBullets: enemyBullets, enemies: enemies, boss: boss, hasShield: SkillManager.hasShield() && shieldCooldown <= 0, ), ), ), // HUD Positioned( top: 40, left: 10, child: Row( children: List.generate( maxHealth, (i) => Icon( Icons.favorite, color: i < health ? Colors.red : Colors.grey.withOpacity(0.3), size: 24, ), ), ), ), Positioned( top: 40, right: 10, child: Column( crossAxisAlignment: CrossAxisAlignment.end, children: [ Text('Score: $score', style: const TextStyle(color: Colors.white, fontSize: 16)), Text('💰 $coins', style: const TextStyle(color: Colors.yellow, fontSize: 16)), ], ), ), if (boss != null) Positioned( top: 80, left: 20, right: 20, child: Column( children: [ const Text('BOSS', style: TextStyle(color: Colors.purpleAccent, fontWeight: FontWeight.bold)), LinearProgressIndicator( value: boss!.health / boss!.maxHealth, backgroundColor: Colors.grey[800], color: Colors.purpleAccent, ), ], ), ), // Pause button Positioned( top: 40, left: MediaQuery.of(context).size.width / 2 - 20, child: IconButton( icon: Icon(isPaused ? Icons.play_arrow : Icons.pause, color: Colors.white), onPressed: () { setState(() { isPaused = !isPaused; }); }, ), ), if (isGameOver) _buildGameOverScreen(), ], ), ); } Widget _buildGameOverScreen() { return Container( color: Colors.black.withOpacity(0.85), child: Center( child: Column( mainAxisAlignment: MainAxisAlignment.center, children: [ const Text('GAME OVER', style: TextStyle(color: Colors.red, fontSize: 32, fontWeight: FontWeight.bold)), const SizedBox(height: 20), Text('Score: $score', style: const TextStyle(color: Colors.white, fontSize: 20)), Text('Coins Earned: $coins', style: const TextStyle(color: Colors.yellow, fontSize: 20)), const SizedBox(height: 40), ElevatedButton( onPressed: _restart, child: const Text('RESTART'), ), const SizedBox(height: 10), ElevatedButton( onPressed: () { Navigator.pushReplacement( context, MaterialPageRoute(builder: (_) => const SkillTreeScreen()), ); }, child: const Text('SKILL TREE'), ), const SizedBox(height: 10), TextButton( onPressed: () => Navigator.pop(context), child: const Text('MAIN MENU', style: TextStyle(color: Colors.white)), ), ], ), ), ); } } // ============================================ // CUSTOM PAINTER (RENDERING) // ============================================ class GamePainter extends CustomPainter { final List<Star> stars; final double playerX, playerY; final List<Bullet> bullets, enemyBullets; final List<Enemy> enemies; final Boss? boss; final bool hasShield; GamePainter({ required this.stars, required this.playerX, required this.playerY, required this.bullets, required this.enemyBullets, required this.enemies, required this.boss, required this.hasShield, }); @override void paint(Canvas canvas, Size size) { // Draw stars final starPaint = Paint()..color = Colors.white; for (var star in stars) { canvas.drawRect(Rect.fromLTWH(star.x, star.y, star.size, star.size), starPaint); } // Draw player ship (pixel triangle) final shipPaint = Paint()..color = Colors.cyanAccent; Path path = Path(); path.moveTo(playerX, playerY - 20); path.lineTo(playerX - 15, playerY + 15); path.lineTo(playerX, playerY + 8); path.lineTo(playerX + 15, playerY + 15); path.close(); canvas.drawPath(path, shipPaint); if (hasShield) { final shieldPaint = Paint() ..color = Colors.blueAccent.withOpacity(0.3) ..style = PaintingStyle.stroke ..strokeWidth = 3; canvas.drawCircle(Offset(playerX, playerY), 30, shieldPaint); } // Draw player bullets final bulletPaint = Paint()..color = Colors.greenAccent; for (var b in bullets) { canvas.drawRect(Rect.fromLTWH(b.x - 2, b.y - 8, 4, 16), bulletPaint); } // Draw enemy bullets final enemyBulletPaint = Paint()..color = Colors.redAccent; for (var b in enemyBullets) { canvas.drawCircle(Offset(b.x, b.y), 4, enemyBulletPaint); } // Draw enemies (pixel squares) for (var enemy in enemies) { final enemyPaint = Paint()..color = enemy.color; canvas.drawRect( Rect.fromCenter(center: Offset(enemy.x, enemy.y), width: enemy.size, height: enemy.size), enemyPaint, ); // Inner detail canvas.drawRect( Rect.fromCenter(center: Offset(enemy.x, enemy.y), width: enemy.size * 0.5, height: enemy.size * 0.5), Paint()..color = Colors.black.withOpacity(0.3), ); } // Draw boss if (boss != null) { final bossPaint = Paint()..color = boss!.color; canvas.drawRect( Rect.fromCenter(center: Offset(boss!.x, boss!.y), width: boss!.size, height: boss!.size), bossPaint, ); canvas.drawRect( Rect.fromCenter(center: Offset(boss!.x, boss!.y), width: boss!.size * 0.6, height: boss!.size * 0.6), Paint()..color = Colors.black.withOpacity(0.4), ); } } @override bool shouldRepaint(covariant GamePainter oldDelegate) => true; }